    if (c >= 0 && pos[c]) { now.setAttribute('cx', pos[c][0]); now.setAttribute('cy', pos[c][1]); now.setAttribute('r', planar ? 17 : 15); now.setAttribute('visibility', 'visible'); }
    else if (c === 4 && rim) { now.setAttribute('cx', 0); now.setAttribute('cy', 0); now.setAttribute('r', 122); now.setAttribute('visibility', 'visible'); }
